private int _step = 1;
private const int TotalSteps = 5;
private Player? _player;
private bool _saving = false;
private string ProgressWidth => $"{(_step * 100) / TotalSteps}%";
private void Next() { if (_step < TotalSteps) _step++; }
private void Back() { if (_step > 1) _step--; }
private async Task FinishTutorial()
{
    if (_player == null || _saving) return;
    _saving = true;
    await GameSvc.CompleteTutorialAsync(_player.Id);
    Nav.NavigateTo("/map");
}

In OnInitializedAsync: load player using IHttpContextAccessor to get the current user's name/id, then query Db.Players to find the Player record whose UserId matches. Look at how Map.razor or ZonePage.razor does this and follow the exact same pattern.

