/* CodeQuest Fantasy RPG Theme */
:root {
  --color-bg: #0f0f1a;
  --color-panel: #16213e;
  --color-panel-alt: #1a2a4a;
  --color-accent: #e94560;
  --color-accent-glow: rgba(233, 69, 96, 0.25);
