    radial-gradient(ellipse at 80% 20%, rgba(233, 69, 96, 0.05) 0%, transparent 50%);
  background-attachment: fixed;
}

h1, h2, h3, h4, h5 {
  font-family: var(--font-heading);
  color: var(--color-text);
  letter-spacing: 0.03em;
}

a { color: var(--color-teal); text-decoration: none; transition: color var(--transition); }
a:hover { color: var(--color-accent); }

.panel {
  background: var(--color-panel);
  border: 1px solid rgba(233, 69, 96, 0.3);
  border-radius: var(--radius);
  padding: 1.5rem;
  margin-bottom: 1rem;
  box-shadow: 0 4px 24px rgba(0, 0, 0, 0.4), 0 0 0 1px rgba(233, 69, 96, 0.05);
